function campaignSourceFields(type) {
	if (type === "HeroAlt") return [
		{
			name: "headingLogo",
			type: "upload",
			relationTo: "media"
		},
		{
			name: "highlightTitle",
			type: "text"
		},
		{
			name: "highlightText",
			type: "textarea"
		},
		{
			name: "backgroundOverlay",
			type: "select",
			defaultValue: "standard",
			options: [
				"none",
				"off",
				"subtle",
				"standard",
				"strong"
			]
		},
		{
			name: "textPanelColor",
			type: "select",
			defaultValue: "primary",
			options: [
				"primary",
				"accent",
				"foreground",
				"background",
				"white"
			]
		},
		{
			name: "textPanelOpacity",
			type: "select",
			defaultValue: "translucent",
			options: ["translucent", "solid"]
		}
	];
	if ([
		"AboutAlt",
		"CardsGridAlt",
		"PalmCardPointsAlt",
		"TestimonialAlt",
		"PalmCardAlt",
		"PalmCardContactAlt"
	].includes(type)) {
		const fields = [{
			name: "intro",
			type: "textarea"
		}];
		if (type === "PalmCardAlt") fields.push({
			name: "quote",
			type: "textarea"
		}, {
			name: "quoteAttribution",
			type: "text"
		});
		if (type === "PalmCardContactAlt") fields.push({
			name: "electionDay",
			type: "text"
		}, {
			name: "earlyVote",
			type: "text"
		}, {
			name: "phone",
			type: "text"
		}, {
			name: "email",
			type: "email"
		}, {
			name: "website",
			type: "text"
		}, {
			name: "qrImage",
			type: "upload",
			relationTo: "media"
		}, {
			name: "qrCaption",
			type: "text"
		}, {
			name: "disclaimer",
			type: "text"
		});
		return fields;
	}
	if (type === "PalmCardBioAlt") return [{
		name: "quote",
		type: "textarea"
	}, {
		name: "quoteAttribution",
		type: "text"
	}];
	return [];
}
function campaignNestedField(collection) {
	return {
		name: collection,
		type: "array",
		labels: {
			singular: collection === "columns" ? "Column" : collection === "tabs" ? "Tab" : "Card",
			plural: collection
		},
		fields: [
			{
				name: "label",
				type: "text"
			},
			{
				name: "heading",
				type: "text"
			},
			{
				name: "text",
				type: "textarea"
			},
			{
				name: "image",
				type: "upload",
				relationTo: "media"
			},
			{
				name: "blocks",
				type: "blocks",
				blocks: nestedElementBlocks
			}
		]
	};
}
function createCampaignAltBlock(definition) {
	return {
		slug: definition.type,
		labels: {
			singular: definition.label,
			plural: `${definition.label} blocks`
		},
		admin: { group: definition.palette === "elements" ? "Campaign elements" : definition.palette === "rows" ? "Campaign rows" : "Campaign sections" },
		fields: [
			{
				name: "variant",
				type: "select",
				defaultValue: definition.variants[0],
				options: [...definition.variants]
			},
			...definition.presentations ? [{
				name: "presentation",
				type: "select",
				defaultValue: definition.presentations[0],
				options: [...definition.presentations]
			}] : [],
			{
				name: "eyebrow",
				type: "text"
			},
			{
				name: "heading",
				type: "textarea"
			},
			{
				name: "body",
				type: "textarea"
			},
			{
				name: "media",
				type: "upload",
				relationTo: "media"
			},
			{
				name: "backgroundMedia",
				type: "upload",
				relationTo: "media"
			},
			{
				name: "primaryLabel",
				type: "text"
			},
			{
				name: "primaryUrl",
				type: "text"
			},
			{
				name: "secondaryLabel",
				type: "text"
			},
			{
				name: "secondaryUrl",
				type: "text"
			},
			{
				name: "items",
				type: "array",
				labels: {
					singular: "Item",
					plural: "Items"
				},
				fields: campaignItemFields
			},
			...campaignSourceFields(definition.type),
			...definition.nestedCollection ? [campaignNestedField(definition.nestedCollection)] : []
		]
	};
}
